OPJ_BOOL read_and_decode_rle4(FILE *IN, OPJ_UINT8 *pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    OPJ_UINT32 row, col;
    OPJ_UINT32 pixel_count = 0;
    OPJ_UINT8 pixel_val;
    OPJ_UINT32 expected_pixel_count = width * height;
    OPJ_UINT8 *pDest = pData;

    for (row = 0; row < height; ++row) {
        for (col = 0; col < width; ) {
            if (fread(&pixel_val, sizeof(OPJ_UINT8), 1, IN) != 1) {
                return OPJ_FALSE;
            }

            if (pixel_val == 0x00) {
                // Absolute mode
                OPJ_UINT8 num_pixels;
                if (fread(&num_pixels, sizeof(OPJ_UINT8), 1, IN) != 1) {
                    return OPJ_FALSE;
                }

                if (fread(pDest, sizeof(OPJ_UINT8), num_pixels, IN) != num_pixels) {
                    return OPJ_FALSE;
                }

                pDest += num_pixels;
                col += num_pixels;
            } else {
                // Encoded mode
                if (fread(&pixel_val, sizeof(OPJ_UINT8), 1, IN) != 1) {
                    return OPJ_FALSE;
                }

                while (col < width) {
                    *pDest = pixel_val;
                    pDest++;
                    col++;
                    pixel_count++;

                    if (pixel_count % stride == 0 && col < width) {
                        // End of row
                        break;
                    }
                }
            }
        }

        // Move to the start of the next row
        pDest += stride - (width % stride ? width % stride : stride);
    }

    if (pixel_count != expected_pixel_count) {
        return OPJ_FALSE;
    }

    return OPJ_TRUE;
}

OPJ_BOOL read_and_decode_rle4(FILE* IN, OPJ_UINT8* pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    OPJ_UINT32 row, col;
    OPJ_UINT32 pixel_index = 0;
    OPJ_UINT8 byte;

    for (row = 0; row < height; row++) {
        for (col = 0; col < stride; ) {
            if (fread(&byte, 1, 1, IN) != 1) {
                return OPJ_FALSE;
            }

            if (byte == 0x00) {
                // Absolute mode: read next byte and copy it directly
                if (fread(&byte, 1, 1, IN) != 1) {
                    return OPJ_FALSE;
                }
                if (pixel_index >= width) {
                    return OPJ_FALSE;
                }
                pData[row * stride + pixel_index++] = byte;
                col++;
            } else {
                // Encoded mode: byte represents the number of pixels to set to 0
                OPJ_UINT32 count = byte;
                if (pixel_index + count > width) {
                    return OPJ_FALSE;
                }
                for (OPJ_UINT32 i = 0; i < count; i++) {
                    pData[row * stride + pixel_index++] = 0;
                }
                col += count;
            }
        }

        if (pixel_index != width) {
            return OPJ_FALSE;
        }
        pixel_index = 0;
    }

    if (pixel_index != width) {
        return OPJ_FALSE;
    }

    return OPJ_TRUE;
}

OPJ_BOOL decode_rle4_bitmap(FILE *IN, OPJ_UINT8 *pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    OPJ_UINT32 expected_pixel_count = width * height;
    OPJ_UINT32 pixel_count = 0;
    OPJ_UINT8 byte;
    OPJ_UINT32 i = 0;
    OPJ_UINT32 row = 0;
    OPJ_UINT32 col = 0;

    while (pixel_count < expected_pixel_count && !feof(IN)) {
        if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
            return OPJ_FALSE;
        }

        if (byte & 0x80) {
            /* Absolute mode: write the next 7 bytes directly */
            OPJ_UINT32 count = (byte & 0x7F);
            for (OPJ_UINT32 j = 0; j < count && pixel_count < expected_pixel_count; ++j) {
                OPJ_UINT8 pixel;
                if (fread(&pixel, sizeof(OPJ_UINT8), 1, IN) != 1) {
                    return OPJ_FALSE;
                }

                pData[i] = pixel;
                ++pixel_count;

                i = (row * stride) + (col * 1);
                ++col;
                if (col >= width) {
                    col = 0;
                    ++row;
                }
            }
        } else {
            /* RLE mode: repeat the next byte (byte & 0x7F) times */
            OPJ_UINT8 pixel;
            if (fread(&pixel, sizeof(OPJ_UINT8), 1, IN) != 1) {
                return OPJ_FALSE;
            }

            OPJ_UINT32 count = (byte & 0x7F);
            for (OPJ_UINT32 j = 0; j < count && pixel_count < expected_pixel_count; ++j) {
                pData[i] = pixel;
                ++pixel_count;

                i = (row * stride) + (col * 1);
                ++col;
                if (col >= width) {
                    col = 0;
                    ++row;
                }
            }
        }
    }

    if (pixel_count != expected_pixel_count) {
        return OPJ_FALSE;
    }

    return OPJ_TRUE;
}

OPJ_BOOL decode_rle4_bitmap(FILE* IN, OPJ_UINT8* pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    OPJ_UINT32 expected_pixel_count = width * height;
    OPJ_UINT32 pixel_count = 0;
    OPJ_UINT8 byte;
    OPJ_UINT32 byte_index = 0;
    OPJ_UINT32 row = 0;
    OPJ_UINT32 col = 0;

    while (pixel_count < expected_pixel_count && !feof(IN)) {
        if (fread(&byte, 1, 1, IN) != 1) {
            return OPJ_FALSE;
        }

        if ((byte & 0x80) == 0) {
            // Absolute mode
            for (OPJ_UINT32 i = 0; i < 8 && pixel_count < expected_pixel_count; ++i, ++pixel_count) {
                pData[byte_index] = (byte >> (7 - i)) & 0x01;
                byte_index += stride / sizeof(OPJ_UINT8);
                if (byte_index >= stride) {
                    byte_index = 0;
                }
            }
        }
        else {
            // Encoded mode
            OPJ_UINT8 run_length = (byte & 0x7F) + 1;
            OPJ_UINT8 color = (byte >> 7) & 0x01;

            for (OPJ_UINT32 i = 0; i < 8 && pixel_count < expected_pixel_count; ++i, ++pixel_count) {
                pData[byte_index] = color;
                byte_index += stride / sizeof(OPJ_UINT8);
                if (byte_index >= stride) {
                    byte_index = 0;
                }
            }
        }
    }

    if (pixel_count != expected_pixel_count) {
        return OPJ_FALSE;
    }

    return OPJ_TRUE;
}

OPJ_BOOL decode_rle4_bitmap(FILE* IN, OPJ_UINT8* pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    OPJ_UINT32 expected_pixels = width * height;
    OPJ_UINT32 pixels_written = 0;
    OPJ_UINT8 byte;
    OPJ_UINT32 row = 0;
    OPJ_UINT32 col = 0;

    while (row < height && fread(&byte, sizeof(OPJ_UINT8), 1, IN) == 1) {
        if (byte & 0x80) {
            /* Absolute mode */
            OPJ_UINT32 count = (byte & 0x7F) + 1;
            for (OPJ_UINT32 i = 0; i < count && row < height; i++) {
                if (col >= width) {
                    row++;
                    col = 0;
                    continue;
                }
                OPJ_UINT8 value;
                if (fread(&value, sizeof(OPJ_UINT8), 1, IN) != 1) {
                    return OPJ_FALSE;
                }
                pData[row * stride + (col >> 1)] = (col & 0x01) ? (value << 4) : value;
                col += 1;
                pixels_written++;
            }
        } else {
            /* Encoded mode */
            OPJ_UINT32 count = (byte & 0x7F) + 1;
            OPJ_UINT8 value;
            if (fread(&value, sizeof(OPJ_UINT8), 1, IN) != 1) {
                return OPJ_FALSE;
            }
            for (OPJ_UINT32 i = 0; i < count && row < height; i++) {
                if (col >= width) {
                    row++;
                    col = 0;
                    continue;
                }
                pData[row * stride + (col >> 1)] = (col & 0x01) ? (value << 4) : value;
                col += 1;
                pixels_written++;
            }
        }
    }

    if (pixels_written != expected_pixels) {
        return OPJ_FALSE;
    }

    return OPJ_TRUE;
}
